CREATE TABLE IF NOT EXISTS board_sessions(id VARCHAR(80) PRIMARY KEY,user_id VARCHAR(80) NOT NULL,level_id VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL,run JSON NOT NULL,score INT NOT NULL DEFAULT 0,stars INT NOT NULL DEFAULT 0,started_at DATETIME(3) NOT NULL,finished_at DATETIME(3) NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX board_sessions_user(user_id,status),INDEX board_sessions_level(level_id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS board_results(id VARCHAR(80) PRIMARY KEY,session_id VARCHAR(80) NOT NULL UNIQUE,user_id VARCHAR(80) NOT NULL,level_id VARCHAR(80) NOT NULL,chapter INT NOT NULL,kind VARCHAR(16) NOT NULL,score INT NOT NULL,stars INT NOT NULL,hints INT NOT NULL DEFAULT 0,failures INT NOT NULL DEFAULT 0,evidence_digest CHAR(64) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX board_results_user(user_id,level_id),INDEX board_results_rank(score),FOREIGN KEY(user_id) REFERENCES users(id));
